using UnityEngine;

namespace Mas3D.Actions
{
    /// <summary>
    /// Task 7 of docs/superpowers/plans/2026-11-04-unity-actions-p4.md: the second seat on the bed.
    /// anchors.json has one bed slot (S2, the mattress centre line), so "sit together" needs a twin
    /// slot for the player. It is derived, never written back: anchors.json is generated by
    /// tools/anchor-plan.mjs and the player would overwrite a hand edit on the next build.
    /// </summary>
    public static class ActionSeats
    {
        /// <summary>
        /// Default distance along her right hand from her hips to the player's. 0.70 m keeps the
        /// player's capsule (radius 0.30) and her body capsule (radius 0.20) apart with 0.20 m to
        /// spare, and it is what <c>ActionSitTogetherTests.TheTwoBodiesStayFortyCentimetresApart</c>
        /// pins as the floor.
        /// </summary>
        public const float BedPairOffset = 0.70f;

        /// <summary>
        /// The player's half of a bed seat: the same height, surface and facing, moved
        /// <paramref name="offset"/> metres along her right hand. Her facing decides "right": at S2
        /// (facingY 0, looking down +z) that is +x, so the pair lands on the mattress beside her
        /// instead of in front of her knees.
        /// </summary>
        public static SeatEntry BedPair(SeatEntry seat, float offset = BedPairOffset)
        {
            if (seat == null) return null;

            var right = Quaternion.Euler(0f, seat.facingY, 0f) * Vector3.right;
            return new SeatEntry
            {
                id = seat.id + "-pair",
                mesh = seat.mesh,
                x = seat.x + right.x * offset,
                y = seat.y,
                z = seat.z + right.z * offset,
                topY = seat.topY,
                facingY = seat.facingY,
            };
        }
    }
}
